1	// Package testutil provides helpers for driving Bubble Tea models in tests.
2	//
3	// The views in this project are testable without a terminal because of two
4	// properties the codebase already guarantees:
5	//
6	//   - Constructors are pure. New(cfg) performs no I/O; Docker and network calls
7	//     are issued from Init() as tea.Cmd values.
8	//   - Update() is a pure function (Model, Msg) -> (Model, Cmd). Rule 110 forbids
9	//     mutating the model inside a Cmd, so feeding synthetic messages to Update()
10	//     fully determines the resulting state.
11	//
12	// These helpers therefore build messages and drain commands; they never spin up
13	// a tea.Program.
14	package testutil
15	
16	import (
17		"fmt"
18		"reflect"
19		"strings"
20		"time"
21	
22		tea "github.com/charmbracelet/bubbletea"
23	
24		"github.com/anthnel/devdesk/internal/ui/shortcut"
25	)
26	
27	// FastTimers shortens a package-level timer for the length of the test.
28	//
29	// Msgs and MsgOf run the commands they are handed, and a footer message's
30	// expiry is a tea.Tick that really sleeps for the three seconds Rule 128 gives
31	// it (components.FooterMsgDuration). A view batches that timer with whatever
32	// else it returns, so one assertion on such a command costs the suite three
33	// full seconds.
34	//
35	// It takes a pointer rather than importing the duration it shortens: this
36	// package is imported by components' own tests, and reaching back into
37	// components from here would be an import cycle.
38	//
39	//	testutil.FastTimers(t, &components.FooterMsgDuration)
40	func FastTimers(t interface{ Cleanup(func()) }, d *time.Duration) {
41		restore := *d
42		*d = time.Millisecond
43		t.Cleanup(func() { *d = restore })
44	}
45	
46	// namedKeys maps the key names used throughout the views (they all dispatch on
47	// tea.KeyMsg.String()) onto the key types that render back to those names.
48	// The space is deliberately absent: see spaceKey. The ctrl+a..ctrl+z names are
49	// computed by Key rather than listed.
50	var namedKeys = map[string]tea.KeyType{
51		"enter":     tea.KeyEnter,
52		"esc":       tea.KeyEsc,
53		"escape":    tea.KeyEscape,
54		"up":        tea.KeyUp,
55		"down":      tea.KeyDown,
56		"left":      tea.KeyLeft,
57		"right":     tea.KeyRight,
58		"tab":       tea.KeyTab,
59		"shift+tab": tea.KeyShiftTab,
60		"backspace": tea.KeyBackspace,
61		"delete":    tea.KeyDelete,
62		"insert":    tea.KeyInsert,
63		"home":      tea.KeyHome,
64		"end":       tea.KeyEnd,
65		"pgup":      tea.KeyPgUp,
66		"pgdown":    tea.KeyPgDown,
67		"f1":        tea.KeyF1,
68		"f2":        tea.KeyF2,
69		"f3":        tea.KeyF3,
70		"f4":        tea.KeyF4,
71		"f5":        tea.KeyF5,
72		"f6":        tea.KeyF6,
73		"f7":        tea.KeyF7,
74		"f8":        tea.KeyF8,
75		"f9":        tea.KeyF9,
76		"f10":       tea.KeyF10,
77		"f11":       tea.KeyF11,
78		"f12":       tea.KeyF12,
79	}
80	
81	// spaceKey is the one place the space key is built. In bubbletea v1 the space
82	// is its own key type but also carries its rune, as a real terminal delivers it.
83	func spaceKey() tea.KeyMsg {
84		return tea.KeyMsg{Type: tea.KeySpace, Runes: []rune{' '}}
85	}
86	
87	// Key builds the tea.KeyMsg a terminal would deliver for the named key.
88	//
89	// Accepted names, and nothing else (anything unknown panics, so a typo fails
90	// loudly instead of silently typing literal runes):
91	//   - the names in namedKeys ("enter", "esc", "shift+tab", "pgdown", "f5"...);
92	//   - "ctrl+a" to "ctrl+z", computed;
93	//   - " " or "space", the space key;
94	//   - a single rune ("y", ":"), a KeyRunes message;
95	//   - an "alt+" prefix on any of the above, which sets Alt: Key("alt+:") is a
96	//     colon carrying Alt, not the five runes "alt+:".
97	//
98	// For several characters typed in a row, use Type; for a bracketed paste, Paste.
99	//
100	// The space is built, never compared through String(): in bubbletea v1
101	// KeyMsg.String() of the space is " ", in v2 it is "space". The v2 equivalents
102	// of what this function builds, for the migration that will replace it:
103	//
104	//	space:    tea.KeyPressMsg{Code: tea.KeySpace, Text: " "}
105	//	rune r:   tea.KeyPressMsg{Code: r, Text: string(r)}
106	//	ctrl+x:   tea.KeyPressMsg{Code: 'x', Mod: tea.ModCtrl}
107	//	alt+...:  the same with Mod: tea.ModAlt
108	//	enter:    tea.KeyPressMsg{Code: tea.KeyEnter}
109	func Key(name string) tea.KeyMsg {
110		if rest, isAlt := strings.CutPrefix(name, "alt+"); isAlt && rest != "" {
111			msg := Key(rest)
112			msg.Alt = true
113			return msg
114		}
115		if name == " " || name == "space" {
116			return spaceKey()
117		}
118		if kt, ok := namedKeys[name]; ok {
119			return tea.KeyMsg{Type: kt}
120		}
121		if letter, ok := strings.CutPrefix(name, "ctrl+"); ok && len(letter) == 1 && letter[0] >= 'a' && letter[0] <= 'z' {
122			return tea.KeyMsg{Type: tea.KeyCtrlA + tea.KeyType(letter[0]-'a')}
123		}
124		if r := []rune(name); len(r) == 1 {
125			return tea.KeyMsg{Type: tea.KeyRunes, Runes: r}
126		}
127		panic(fmt.Sprintf("testutil.Key: unknown key name %q (use Type for several characters, Paste for a paste)", name))
128	}
129	
130	// Keys builds one message per name, for feeding a sequence to Update().
131	func Keys(names ...string) []tea.Msg {
132		msgs := make([]tea.Msg, 0, len(names))
133		for _, n := range names {
134			msgs = append(msgs, Key(n))
135		}
136		return msgs
137	}
138	
139	// Type builds one rune message per character of s, reproducing a user typing
140	// into a text input. Use this instead of Key(s) when the target is a
141	// bubbles/textinput: it consumes runes one keypress at a time.
142	func Type(s string) []tea.Msg {
143		msgs := make([]tea.Msg, 0, len(s))
144		for _, r := range s {
145			if r == ' ' {
146				msgs = append(msgs, spaceKey())
147				continue
148			}
149			msgs = append(msgs, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{r}})
150		}
151		return msgs
152	}
153	
154	// Resize builds the window size message views use to lay themselves out.
155	func Resize(width, height int) tea.Msg {
156		return tea.WindowSizeMsg{Width: width, Height: height}
157	}
158	
159	// Msgs executes cmd and returns every message it produced, flattening the
160	// tea.Batch and tea.Sequence trees. A nil command, or one returning nil, yields
161	// no messages.
162	//
163	// The command runs synchronously on the calling goroutine. Do not pass a command
164	// that sleeps or performs I/O — tea.Tick blocks for its whole duration, and the
165	// Docker runners shell out. Assert on the command's identity or on model state
166	// instead for those.
167	func Msgs(cmd tea.Cmd) []tea.Msg {
168		if cmd == nil {
169			return nil
170		}
171		msg := cmd()
172		if msg == nil {
173			return nil
174		}
175		if batch, ok := msg.(tea.BatchMsg); ok {
176			var out []tea.Msg
177			for _, c := range batch {
178				out = append(out, Msgs(c)...)
179			}
180			return out
181		}
182		if seq, ok := sequenced(msg); ok {
183			var out []tea.Msg
184			for _, c := range seq {
185				out = append(out, Msgs(c)...)
186			}
187			return out
188		}
189		return []tea.Msg{msg}
190	}
191	
192	// sequenced reports whether msg is what tea.Sequence returns, and unpacks the
193	// commands it holds.
194	//
195	// tea.Batch answers with the exported tea.BatchMsg, but the equivalent for
196	// tea.Sequence is unexported — the runtime is its only intended reader, and it
197	// runs the commands one after another rather than concurrently. Its underlying
198	// type is []tea.Cmd, so reflection recovers them without depending on the name.
199	// Order is preserved, which is the whole point of a sequence: a view that emits
200	// "scan starting" before the scan itself relies on the first message arriving
201	// first.
202	func sequenced(msg tea.Msg) ([]tea.Cmd, bool) {
203		value := reflect.ValueOf(msg)
204		if value.Kind() != reflect.Slice || value.Type().Elem() != reflect.TypeFor[tea.Cmd]() {
205			return nil, false
206		}
207		// The element type was just checked, so every assertion below holds; a nil
208		// entry comes back as a nil tea.Cmd, which Msgs already ignores.
209		cmds := make([]tea.Cmd, 0, value.Len())
210		for i := range value.Len() {
211			cmds = append(cmds, value.Index(i).Interface().(tea.Cmd))
212		}
213		return cmds, true
214	}
215	
216	// Msg executes cmd and returns the single message it produced, or nil.
217	// It is the common case of Msgs for commands that emit exactly one message.
218	func Msg(cmd tea.Cmd) tea.Msg {
219		msgs := Msgs(cmd)
220		if len(msgs) == 0 {
221			return nil
222		}
223		return msgs[0]
224	}
225	
226	// MsgOf reports whether cmd produced a message of type T, returning the first
227	// such message. It searches through batched commands.
228	func MsgOf[T tea.Msg](cmd tea.Cmd) (T, bool) {
229		for _, m := range Msgs(cmd) {
230			if v, ok := m.(T); ok {
231				return v, true
232			}
233		}
234		var zero T
235		return zero, false
236	}
237	
238	// ── Shortcuts (Rule 130) ─────────────────────────────────────────────────────
239	
240	// HasShortcut reports whether the key is advertised at all, greyed or not.
241	func HasShortcut(shortcuts shortcut.Shortcuts, key string) bool {
242		_, ok := findShortcut(shortcuts, key)
243		return ok
244	}
245	
246	// ShortcutDisabled reports whether the key is advertised but greyed out.
247	//
248	// A key that is missing altogether is **not** disabled — it is absent, which is
249	// a different failure. Rule 130 says an entry is greyed, never dropped, so a
250	// test that conflated the two would pass on the very regression it exists to
251	// catch; assert HasShortcut alongside it.
252	func ShortcutDisabled(shortcuts shortcut.Shortcuts, key string) bool {
253		s, ok := findShortcut(shortcuts, key)
254		return ok && s.Disabled
255	}
256	
257	// ShortcutEnabled reports whether the key is advertised and acts.
258	func ShortcutEnabled(shortcuts shortcut.Shortcuts, key string) bool {
259		s, ok := findShortcut(shortcuts, key)
260		return ok && !s.Disabled
261	}
262	
263	// ShortcutKeys is the advertised keys in order — what a test compares across
264	// states to check the column does not move.
265	func ShortcutKeys(shortcuts shortcut.Shortcuts) []string {
266		keys := make([]string, 0, len(shortcuts))
267		for _, s := range shortcuts {
268			keys = append(keys, s.Key)
269		}
270		return keys
271	}
272	
273	func findShortcut(shortcuts shortcut.Shortcuts, key string) (shortcut.Shortcut, bool) {
274		for _, s := range shortcuts {
275			if s.Key == key {
276				return s, true
277			}
278		}
279		return shortcut.Shortcut{}, false
280	}
281	
282	// Paste builds the message a bracketed paste of s delivers: one KeyRunes
283	// message carrying the whole text, flagged Paste.
284	func Paste(s string) tea.Msg {
285		return tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune(s), Paste: true}
286	}
287	
288	// IsText reports whether msg is a key message carrying text, typed or pasted:
289	// what a text input would insert. It replaces reading key.Type directly, which
290	// a v2 migration would break.
291	func IsText(msg tea.Msg) bool {
292		km, ok := msg.(tea.KeyMsg)
293		return ok && (km.Type == tea.KeyRunes || km.Type == tea.KeySpace)
294	}
295	
296	// Text returns the text a key message carries, typed or pasted, and whether
297	// msg is such a message. It replaces reading KeyMsg.Runes directly, which a
298	// v2 migration would break.
299	func Text(msg tea.Msg) (string, bool) {
300		if !IsText(msg) {
301			return "", false
302		}
303		return string(msg.(tea.KeyMsg).Runes), true
304	}
